import java.io.*;import java.util.*;import java.util.stream.*;class Result {    public static String isBalanced(String s) {        Deque<Character> stack = new ArrayDeque<>();        for (int i = 0; i < s.length(); i++) {            char c = s.charAt(i);            if (c == '(' || c == '[' || c == '{') {                stack.push(c);            } else {                if (stack.isEmpty()) {                    return "NO";                }                char top = stack.pop();                if (!matches(top, c)) {                    return "NO";                }            }        }        return stack.isEmpty() ? "YES" : "NO";    }    private static boolean matches(char open, char close) {        return (open == '(' && close == ')') || (open == '[' && close == ']') || (open == '{' && close == '}');    } }public class Solution {    public static void main(String[] args) throws IOException {        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));        BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));        int t = Integer.parseInt(bufferedReader.readLine().trim());        for (int i = 0; i < t; i++) {            String s = bufferedReader.readLine();            String result = Result.isBalanced(s);            bufferedWriter.write(result);            bufferedWriter.newLine();        }        bufferedReader.close();        bufferedWriter.close();    } }